20	    private static final class CombinationCounts {
21	
22	        private final int[] countsBySum;
23	        private final int targetSum;
24	
25	        private CombinationCounts(int targetSum) {
26	            this.targetSum = targetSum;
27	            this.countsBySum = new int[targetSum + 1];
28	            countsBySum[0] = 1;
29	        }
30	
31	        static CombinationCounts forTarget(int targetSum) {
32	            return new CombinationCounts(targetSum);
33	        }
34	
35	        // Process each coin once so combinations are counted without regard to order.
36	        void addCoin(int coin) {
37	            for (int currentSum = coin; currentSum <= targetSum; currentSum++) {
38	                countsBySum[currentSum] += countsBySum[currentSum - coin];
